package com.hotelmanagement.hms.housekeeping.model; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="housekeeping_tasks") public class HousekeepingTask { @Id UUID id=UUID.randomUUID(); @Column(name="hotel_id") UUID hotelId; @Column(name="branch_id") UUID branchId; @Column(name="room_id") UUID roomId; @Column(name="assigned_user_id") UUID assignedUserId; LocalDate taskDate; @Enumerated(EnumType.STRING) HousekeepingTaskStatus status; String notes; protected HousekeepingTask(){} public static HousekeepingTask create(UUID h,UUID b,UUID r,UUID u,LocalDate d,String n){var t=new HousekeepingTask();t.hotelId=h;t.branchId=b;t.roomId=r;t.assignedUserId=u;t.taskDate=d;t.notes=n;t.status=HousekeepingTaskStatus.OPEN;return t;} public UUID getId(){return id;} public HousekeepingTaskStatus getStatus(){return status;} public void status(HousekeepingTaskStatus s){status=s;} }
